    "statement": "A educação grega sempre procurou cultivar o espírito cívico, o orgulho de pertencer a uma cidade livre, a lealdade à comunidade política. Primeiramente, a ênfase recaía sobre o treinamento militar. Entretanto, desde o século VI a.C., primeiro em Atenas, depois no resto da Grécia — exce tuando-se sempre Esparta —, as preocupações militares vinham em segundo lugar. Todavia, educação significava ainda principalmente educação física; para os gregos, estava em primeiro lugar — e assim foi durante longo tempo — a palestra¹ e o ginásio, onde a criança e o adolescente eram treinados nos esportes. A educação grega não só era mais física que intelectual; era também artística, especificamente musical, antes de ser literária.\n\n(H. -I. Marrou. “Educação e retórica”. In: Moses Finley (org.). O legado da\n\nGrécia: uma nova avaliação, 1998. Adaptado.)\n\n1 Palestra: do grego palaistra — local para exercícios corporais.\n\nDe acordo com o excerto, na pólis grega, a educação a partir do século VI a.C.",
