    "statement": "O “Diretório dos Índios” foi estabelecido no Brasil em 1759 para administrar as missões fundadas pelas ordens religiosas. Também denominado Diretório que se deve observar nas povoações dos “índios” do Pará e Maranhão enquanto sua Majestade não mandar o contrário, visava levar a civilização e a cultura da metrópole aos indígenas.\n\n(Angela Vianna Botelho e Liana Maria Reis. Dicionário Histórico Brasil:\n\nColônia e Império, 2008. Adaptado.)\n\nO “Diretório dos Índios”, a fim de cumprir os objetivos referidos no excerto, propunha",
