    "statement": "A criação da Zona Franca de Manaus foi justificada pela ditadura civil-militar com a necessidade de se ocupar uma região despovoada. Era necessário, portanto, dotar a região de “condições de meios de vida” e infraestrutura que atraíssem para ela a força de trabalho e o capital, nacional e estrangeiro, vistos como imprescindíveis para a dinamização das forças produtivas locais, objetivando instaurar na região condições de “rentabilidade econômica global”. De fato, sua criação e desenvolvimento sempre estiveram atrelados a circunstâncias político-econômicas locais, nacionais e mundiais.\n\n(José Seráfico e Marcelo Seráfico. A Zona Franca de Manaus e o\n\ncapitalismo no Brasil, 2005. Adaptado.)\n\nA criação da Zona Franca de Manaus inseriu-se no modelo de",
