    "difficulty": "Difícil",
    "statement": "No Brasil, a migração indígena para os centros urbanos tem se intensificado nos últimos 30 anos implicando tanto desafios particulares para preservar a identidade étnica como a falta de emprego, de acesso à saúde, à educação, à moradia adequada e a outros direitos fundamentais. A vulnerabilidade de povos, famílias ou pessoas indígenas é reconhecida no Relatório da Organização das Nações Unidas sobre a Promoção e a Proteção dos Direitos Humanos de Migrantes no Contexto de Grandes Movimentos. A migração de indígenas para as cidades, voluntária ou forçada, em geral decorre da violação dos direitos, como nos casos em que é motivada pela expulsão dos territórios de origem, insegurança econômica, ausência ou precariedade de serviços básicos.\n\n(Mariana W. V. de Castilho e Ela W. V de Castilho.\n\nConfluências, dezembro de 2023. Adaptado.)\n\nCaracteriza uma consequência da realidade indígena retratada no excerto:",
