    "statement": "Produtores rurais de Apuí, no interior do estado do Amazonas, usam a floresta como aliada e conseguem incrementar produção de café no município. Com 52 hectares de café plantado e beneficiando direta e indiretamente mais de 60 famílias, o projeto Café Apuí é uma experiência bem-sucedida de cultivo. Antes da chegada do projeto, a realidade da produção era bem diferente. Os agricultores plantavam o café da forma tradicional e, depois de um tempo, desistiam do cultivo, porque a plantação não evoluía e o valor pago pelo que conseguiam colher não era satisfatório.\n\n(Cassandra Castro. https://agenciacenarium.com.br, 15.09.2021. Adaptado.)\n\nConsiderando o contexto apresentado, caracterizam ações que contribuíram para a valorização da agricultura familiar em comunidades tradicionais no estado do Amazonas:",
